/**
 * Vizier Local Syntax Highlighter (highlight.min.js)
 * Bundled zero-dependency syntax highlighter for code blocks.
 */
(function(global) {
  'use strict';

  const KEYWORDS = new Set([
    'abstract', 'arguments', 'await', 'boolean', 'break', 'byte', 'case', 'catch',
    'char', 'class', 'const', 'continue', 'debugger', 'default', 'delete', 'do',
    'double', 'else', 'enum', 'eval', 'export', 'extends', 'false', 'final',
    'finally', 'float', 'for', 'function', 'goto', 'if', 'implements', 'import',
    'in', 'instanceof', 'int', 'interface', 'let', 'long', 'native', 'new',
    'null', 'package', 'private', 'protected', 'public', 'return', 'short',
    'static', 'super', 'switch', 'synchronized', 'this', 'throw', 'throws',
    'transient', 'true', 'try', 'typeof', 'var', 'void', 'volatile', 'while',
    'with', 'yield', 'def', 'self', 'None', 'True', 'False', 'lambda', 'pass',
    'raise', 'from', 'as', 'async', 'assert', 'nonlocal', 'global', 'elif',
    'npm', 'npx', 'node', 'git', 'docker', 'curl', 'wget', 'sudo', 'apt', 'pip',
    'python', 'bash', 'sh', 'mkdir', 'cd', 'ls', 'rm', 'cp', 'mv', 'echo', 'cat'
  ]);

  function escapeHtml(str) {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function highlightCode(code, lang) {
    if (!code) return '';
    const cleanLang = (lang || '').toLowerCase();
    
    // Split lines or tokenize code
    const lines = code.split('\n');
    const highlightedLines = lines.map(line => {
      // Comments
      if (/^\s*(#|\/\/|\/\*)/.test(line)) {
        return `<span class="hljs-comment">${escapeHtml(line)}</span>`;
      }
      
      let html = escapeHtml(line);

      // Strings (double quotes, single quotes, backticks)
      html = html.replace(/(["'`])(?:(?=(\\?))\2[\s\S])*?\1/g, '<span class="hljs-string">$&</span>');

      // Numbers
      html = html.replace(/\b(\d+(\.\d+)?)\b/g, '<span class="hljs-number">$1</span>');

      // Keywords (avoid replacing inside already wrapped tags)
      html = html.replace(/\b([a-zA-Z_][a-zA-Z0-9_]*)\b/g, function(match, word) {
        if (KEYWORDS.has(word)) {
          return `<span class="hljs-keyword">${word}</span>`;
        }
        return word;
      });

      // Function calls
      html = html.replace(/\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g, function(match, fnName) {
        if (KEYWORDS.has(fnName)) {
          return `<span class="hljs-keyword">${fnName}</span>(`;
        }
        return `<span class="hljs-title function_">${fnName}</span>(`;
      });

      return html;
    });

    return highlightedLines.join('\n');
  }

  global.VizierHighlight = {
    highlight: highlightCode
  };
})(typeof window !== 'undefined' ? window : global);
